18	
19	import java.util.Map;
20	import java.util.Objects;
21	
22	import org.keycloak.util.EnumWithStableIndex;
23	
24	/**
25	 * The decision strategy dictates how the policies associated with a given policy are evaluated and how a final decision
26	 * is obtained.
27	 *
28	 * @author <a href="mailto:psilva@redhat.com">Pedro Igor</a>
29	 */
30	public enum DecisionStrategy implements EnumWithStableIndex {
31	
32	    /**
33	     * Defines that at least one policy must evaluate to a positive decision in order to the overall decision be also positive.
34	     */
35	    AFFIRMATIVE(0),
36	
37	    /**
38	     * Defines that all policies must evaluate to a positive decision in order to the overall decision be also positive.
39	     */
40	    UNANIMOUS(1),
41	
42	    /**
43	     * Defines that the number of positive decisions must be greater than the number of negative decisions. If the number of positive and negative is the same,
44	     * the final decision will be negative.
45	     */
46	    CONSENSUS(2);
47	
48	    private final int stableIndex;
49	    private static final Map<Integer, DecisionStrategy> BY_ID = EnumWithStableIndex.getReverseIndex(values());
50	
51	    private DecisionStrategy(int stableIndex) {
52	        Objects.requireNonNull(stableIndex);
53	        this.stableIndex = stableIndex;
54	    }
55	
56	    @Override
57	    public int getStableIndex() {
58	        return stableIndex;
59	    }
60	
61	    public static DecisionStrategy valueOfInteger(Integer id) {
62	        return id == null ? null : BY_ID.get(id);
63	    }
64	}
