24	/**
25	 * The decision strategy dictates how the policies associated with a given policy are evaluated and how a final decision
26	 * is obtained.
27	 *
28	 * @author <a href="mailto:psilva@redhat.com">Pedro Igor</a>
29	 */
30	public enum Logic implements EnumWithStableIndex {
31	
32	    /**
33	     * Defines that this policy follows a positive logic. In other words, the final decision is the policy outcome.
34	     */
35	    POSITIVE(0),
36	
37	    /**
38	     * Defines that this policy uses a logical negation. In other words, the final decision would be a negative of the policy outcome.
39	     */
40	    NEGATIVE(1);
41	
42	    private final int stableIndex;
43	    private static final Map<Integer, Logic> BY_ID = EnumWithStableIndex.getReverseIndex(values());
44	
45	    private Logic(int stableIndex) {
46	        Objects.requireNonNull(stableIndex);
47	        this.stableIndex = stableIndex;
48	    }
49	
50	    @Override
51	    public int getStableIndex() {
52	        return stableIndex;
53	    }
54	
55	    public static Logic valueOfInteger(Integer id) {
56	        return id == null ? null : BY_ID.get(id);
57	    }
58	}
