344	    /**
345	     * <p> Invoke the method on the instance, with any arguments specified, casting the result of invoking the method to
346	     * the expected return type. </p> <p/> <p> This method wraps {@link Method#invoke(Object, Object...)}, converting
347	     * the checked exceptions that {@link Method#invoke(Object, Object...)} specifies to runtime exceptions. </p> <p/>
348	     * <p> If instructed, this method attempts to set the accessible flag of the method in a {link PrivilegedAction}
349	     * before invoking the method. </p>
350	     *
351	     * @param setAccessible flag indicating whether method should first be set as accessible
352	     * @param method the method to invoke
353	     * @param instance the instance to invoke the method
354	     * @param args the arguments to the method
355	     *
356	     * @return the result of invoking the method, or null if the method's return type is void
357	     *
358	     * @throws RuntimeException if this <code>Method</code> object enforces Java language access control and the
359	     * underlying method is inaccessible or if the underlying method throws an exception or if the initialization
360	     * provoked by this method fails.
361	     * @throws IllegalArgumentException if the method is an instance method and the specified <code>instance</code>
362	     * argument is not an instance of the class or interface declaring the underlying method (or of a subclass or
363	     * implementor thereof); if the number of actual and formal parameters differ; if an unwrapping conversion for
364	     * primitive arguments fails; or if, after possible unwrapping, a parameter value cannot be converted to the
365	     * corresponding formal parameter type by a method invocation conversion.
366	     * @throws NullPointerException if the specified <code>instance</code> is null and the method is an instance
367	     * method.
368	     * @throws ClassCastException if the result of invoking the method cannot be cast to the expectedReturnType
369	     * @throws ExceptionInInitializerError if the initialization provoked by this method fails.
370	     * @see Method#invoke(Object, Object...)
371	     */
372	    public static <T> T invokeMethod(boolean setAccessible, Method method,
373	                                     Class<T> expectedReturnType, Object instance, Object... args) {
374	        if (setAccessible && !method.isAccessible()) {
375	            setAccessible(method);
376	        }
377	
378	        try {
379	            return expectedReturnType.cast(method.invoke(instance, args));
380	        } catch (IllegalAccessException ex) {
381	            throw new RuntimeException(buildInvokeMethodErrorMessage(method, instance, args), ex);
382	        } catch (IllegalArgumentException ex) {
383	            throw new IllegalArgumentException(buildInvokeMethodErrorMessage(method, instance, args), ex);
384	        } catch (InvocationTargetException ex) {
385	            throw new RuntimeException(buildInvokeMethodErrorMessage(method, instance, args), ex.getCause());
386	        } catch (NullPointerException ex) {
387	            NullPointerException ex2 = new NullPointerException(buildInvokeMethodErrorMessage(method, instance, args));
388	            ex2.initCause(ex.getCause());
389	            throw ex2;
390	        } catch (ExceptionInInitializerError e) {
391	            ExceptionInInitializerError e2 = new ExceptionInInitializerError(
392	                    buildInvokeMethodErrorMessage(method, instance, args));
393	            e2.initCause(e.getCause());
394	            throw e2;
395	        }
396	    }
