533	    public static Type[] findInterfaceParameterizedTypes(Class<?> root, ParameterizedType rootType, Class<?> searchedForInterface)
534	    {
535	        Map<String, Type> typeVarMap = populateParameterizedMap(root, rootType);
536	
537	        for (int i = 0; i < root.getInterfaces().length; i++)
538	        {
539	            Class<?> sub = root.getInterfaces()[i];
540	            Type genericSub = root.getGenericInterfaces()[i];
541	            if (sub.equals(searchedForInterface))
542	            {
543	                return extractTypes(typeVarMap, genericSub);
544	            }
545	        }
546	
547	        for (int i = 0; i < root.getInterfaces().length; i++)
548	        {
549	            Type genericSub = root.getGenericInterfaces()[i];
550	            Class<?> sub = root.getInterfaces()[i];
551	
552	            Type[] types = recurseSuperclassForInterface(searchedForInterface, typeVarMap, genericSub, sub);
553	            if (types != null) return types;
554	        }
555	        if (root.isInterface()) return null;
556	
557	        Class<?> superclass = root.getSuperclass();
558	        Type genericSuper = root.getGenericSuperclass();
559	
560	
561	        return recurseSuperclassForInterface(searchedForInterface, typeVarMap, genericSuper, superclass);
562	    }
563	
564	    private static Type[] recurseSuperclassForInterface(Class<?> searchedForInterface, Map<String, Type> typeVarMap, Type genericSub, Class<?> sub)
565	    {
566	        if (genericSub instanceof ParameterizedType)
567	        {
568	            ParameterizedType intfParam = (ParameterizedType) genericSub;
569	            Type[] types = findInterfaceParameterizedTypes(sub, intfParam, searchedForInterface);
570	            if (types != null)
571	            {
572	                return extractTypeVariables(typeVarMap, types);
573	            }
574	        }
575	        else
576	        {
577	            Type[] types = findInterfaceParameterizedTypes(sub, null, searchedForInterface);
578	            if (types != null)
579	            {
580	                return types;
581	            }
582	        }
583	        return null;
584	    }
585	
586	    private static Type[] extractTypeVariables(Map<String, Type> typeVarMap, Type[] types)
587	    {
588	        for (int j = 0; j < types.length; j++)
589	        {
590	            if (types[j] instanceof TypeVariable)
591	            {
592	                TypeVariable tv = (TypeVariable) types[j];
593	                types[j] = typeVarMap.get(tv.getName());
594	            }
595	        }
596	        return types;
597	    }
598	
599	    private static Type[] extractTypes(Map<String, Type> typeVarMap, Type genericSub)
600	    {
601	        if (genericSub instanceof ParameterizedType)
602	        {
603	            ParameterizedType param = (ParameterizedType) genericSub;
604	            Type[] types = param.getActualTypeArguments();
605	            Type[] returnTypes = new Type[types.length];
606	            System.arraycopy(types, 0, returnTypes, 0, types.length);
607	            extractTypeVariables(typeVarMap, returnTypes);
608	            return returnTypes;
609	        }
610	        else
611	        {
612	            return EMPTY_TYPE_ARRAY;
613	        }
614	    }
