31	 */
32	public class PublicKeysWrapper {
33	
34	    private final List<KeyWrapper> keys;
35	    private final Long expirationTime;
36	
37	    public static final PublicKeysWrapper EMPTY = new PublicKeysWrapper(Collections.emptyList());
38	
39	    public PublicKeysWrapper(List<KeyWrapper> keys) {
40	        this(keys, null);
41	    }
42	
43	    public PublicKeysWrapper(List<KeyWrapper> keys, Long expirationTime) {
44	        this.keys = keys;
45	        this.expirationTime = expirationTime;
46	    }
47	
48	    public Long getExpirationTime() {
49	        return expirationTime;
50	     }
51	
52	    public List<KeyWrapper> getKeys() {
53	        return keys;
54	    }
55	
56	    public List<String> getKids() {
57	        return keys.stream()
58	                .map(KeyWrapper::getKid)
59	                .collect(Collectors.toList());
60	    }
61	
62	    /**
63	     * Find an appropriate key given a KID and algorithm.
64	     * Prefer matching on both parameters, but may partially match on KID only. Or if KID is not provided, the
65	     * algorithm. Will use a flagged default client certificate otherwise, if a match is not found.
66	     * @param kid rfc7517 KID parameter
67	     * @param alg rfc7517 alg parameter
68	     * @return {@link KeyWrapper} matching given parameters
69	     */
70	    public KeyWrapper getKeyByKidAndAlg(String kid, String alg) {
71	
72	        Stream<KeyWrapper> potentialMatches = Stream.concat(
73	            keys.stream().filter(keyWrapper -> Objects.equals(kid, keyWrapper.getKid()) && Objects.equals(alg, keyWrapper.getAlgorithm())),
74	            keys.stream().filter(keyWrapper -> Objects.equals(kid, keyWrapper.getKid())));
75	
76	        if (kid == null) {
77	            potentialMatches = Stream.of(
78	                    potentialMatches,
79	                    keys.stream().filter(keyWrapper -> Objects.equals(alg, keyWrapper.getAlgorithmOrDefault())),
80	                    keys.stream().filter(KeyWrapper::isDefaultClientCertificate)
81	                ).flatMap(i -> i);
82	        }
83	
84	        return potentialMatches.findFirst().orElse(null);
85	    }
86	
87	    /**
88	     * Returns the first key that matches the predicate.
89	     * @param predicate The predicate
90	     * @return The first key that matches the predicate or null
91	     */
92	    public KeyWrapper getKeyByPredicate(Predicate<KeyWrapper> predicate) {
93	        return keys.stream().filter(predicate).findFirst().orElse(null);
94	    }
95	}
