19	public class JavaAlgorithm {
20	
21	    public static final String RS256 = "SHA256withRSA";
22	    public static final String RS384 = "SHA384withRSA";
23	    public static final String RS512 = "SHA512withRSA";
24	    public static final String HS256 = "HMACSHA256";
