27	    public static final String ES256 = "SHA256withECDSA";
28	    public static final String ES384 = "SHA384withECDSA";
29	    public static final String ES512 = "SHA512withECDSA";
30	    public static final String PS256 = "SHA256withRSAandMGF1";
31	    public static final String PS384 = "SHA384withRSAandMGF1";
32	    public static final String PS512 = "SHA512withRSAandMGF1";
33	    public static final String Ed25519 = "Ed25519";
34	    public static final String Ed448 = "Ed448";
35	    public static final String AES = "AES";
36	    public static final String ECDSA = "ECDSA";
37	
38	    public static final String SHA256 = "SHA-256";
39	    public static final String SHA384 = "SHA-384";
40	    public static final String SHA512 = "SHA-512";
41	    public static final String SHAKE256 = "SHAKE256";
42	
43	    public static String getJavaAlgorithm(String algorithm) {
44	        return getJavaAlgorithm(algorithm, null);
45	    }
46	
47	    public static String getJavaAlgorithm(String algorithm, String curve) {
48	        switch (algorithm) {
49	            case Algorithm.RS256:
50	                return RS256;
51	            case Algorithm.RS384:
52	                return RS384;
53	            case Algorithm.RS512:
54	                return RS512;
55	            case Algorithm.HS256:
56	                return HS256;
57	            case Algorithm.HS384:
58	                return HS384;
59	            case Algorithm.HS512:
60	                return HS512;
61	            case Algorithm.ES256:
62	                return ES256;
63	            case Algorithm.ES384:
64	                return ES384;
65	            case Algorithm.ES512:
66	                return ES512;
67	            case Algorithm.PS256:
68	                return PS256;
69	            case Algorithm.PS384:
70	                return PS384;
71	            case Algorithm.PS512:
72	                return PS512;
73	            case Algorithm.EdDSA:
74	                if (curve != null) {
75	                    return curve;
76	                }
77	                return Ed25519;
78	            case Algorithm.AES:
79	                return AES;
80	            default:
81	                throw new IllegalArgumentException("Unknown algorithm " + algorithm);
82	        }
83	    }
84	
85	    public static String getJavaAlgorithmForHash(String algorithm) {
86	        return getJavaAlgorithmForHash(algorithm, null);
87	    }
88	
89	    public static String getJavaAlgorithmForHash(String algorithm, String curve) {
90	        switch (algorithm) {
91	            case Algorithm.RS256:
92	                return SHA256;
93	            case Algorithm.RS384:
94	                return SHA384;
95	            case Algorithm.RS512:
96	                return SHA512;
97	            case Algorithm.HS256:
98	                return SHA256;
99	            case Algorithm.HS384:
100	                return SHA384;
101	            case Algorithm.HS512:
102	                return SHA512;
103	            case Algorithm.ES256:
104	                return SHA256;
105	            case Algorithm.ES384:
106	                return SHA384;
107	            case Algorithm.ES512:
108	                return SHA512;
109	            case Algorithm.PS256:
110	                return SHA256;
111	            case Algorithm.PS384:
112	                return SHA384;
113	            case Algorithm.PS512:
114	                return SHA512;
115	            case Algorithm.EdDSA:
116	                if (curve != null) {
117	                    switch (curve) {
118	                        case Algorithm.Ed25519:
119	                            return SHA512;
120	                        case Algorithm.Ed448:
121	                            return SHAKE256;
122	                        default:
123	                            throw new IllegalArgumentException("Unknown curve for EdDSA " + curve);
124	                    }
125	                }
126	                return SHA512;
127	            case Algorithm.AES:
128	                return AES;
129	            default:
130	                throw new IllegalArgumentException("Unknown algorithm " + algorithm);
131	        }
132	    }
133	
134	    public static String getKeyType(String keyAlgorithm) {
135	        switch (keyAlgorithm) {
136	            case KeyType.RSA:
137	                return KeyType.RSA;
138	            case KeyType.EC:
139	            case ECDSA:
140	                return KeyType.EC;
141	            case Algorithm.EdDSA:
142	            case Algorithm.Ed448:
143	            case Algorithm.Ed25519:
144	                return KeyType.OKP;
145	            default:
146	                return KeyType.OCT;
147	        }
148	    }
