155	        return getJavaAlgorithm(algorithm).contains("ECDSA");
156	    }
157	
158	    public static boolean isEddsaJavaAlgorithm(String algorithm) {
159	        return getJavaAlgorithm(algorithm).contains("Ed");
160	    }
