44	    public static boolean validateRedirectBindingSignature(SignatureAlgorithm sigAlg, byte[] rawQueryBytes, byte[] decodedSignature,
45	            KeyLocator locator, String keyId) throws KeyManagementException, VerificationException {
46	        try {
47	            try {
48	                Key key = locator.getKey(keyId);
49	                if (key != null) {
50	                    return validateRedirectBindingSignatureForKey(sigAlg, rawQueryBytes, decodedSignature, key);
51	                }
52	            } catch (KeyManagementException ex) {
53	            }
54	        } catch (SignatureException ex) {
55	            log.debug("Verification failed for key %s: %s", keyId, ex);
56	            log.trace(ex);
57	        }
58	
59	        log.trace("Trying hard to validate XML signature using all available keys.");
60	
61	        for (Key key : locator) {
62	            try {
63	                if (validateRedirectBindingSignatureForKey(sigAlg, rawQueryBytes, decodedSignature, key)) {
64	                    return true;
65	                }
66	            } catch (SignatureException ex) {
67	                log.debug("Verification failed: %s", ex);
68	            }
69	        }
70	
71	        return false;
72	    }
73	
74	    public static boolean validateRedirectBindingSignatureForKey(SignatureAlgorithm sigAlg, byte[] rawQueryBytes, byte[] decodedSignature, Key key)
75	      throws SignatureException {
76	        if (key == null) {
77	            return false;
78	        }
79	
80	        if (!(key instanceof PublicKey)) {
81	            log.warnf("Unusable key for signature validation: %s", key);
82	            return false;
83	        }
84	
85	        Signature signature = sigAlg.createSignature(); // todo plugin signature alg
86	        try {
87	            signature.initVerify((PublicKey) key);
88	        } catch (InvalidKeyException ex) {
89	            log.warnf(ex, "Unusable key for signature validation: %s", key);
90	            return false;
91	        }
92	
93	        signature.update(rawQueryBytes);
94	
95	        return signature.verify(decodedSignature);
96	    }
97	}
