33	 * @author <a href="mailto:psilva@redhat.com">Pedro Igor</a>
34	 */
35	public class TimePolicyProvider implements PolicyProvider {
36	
37	    private static final Logger logger = Logger.getLogger(TimePolicyProvider.class);
38	
39	    static String DEFAULT_DATE_PATTERN = "yyyy-MM-dd HH:mm:ss";
40	
41	    static String CONTEXT_TIME_ENTRY = "kc.time.date_time";
42	
43	    @Override
44	    public void evaluate(Evaluation evaluation) {
45	        Policy policy = evaluation.getPolicy();
46	        SimpleDateFormat dateFormat = new SimpleDateFormat(DEFAULT_DATE_PATTERN);
47	        logger.debugf("Time policy %s evaluating", policy.getName());
48	        try {
49	            String contextTime = null;
50	            EvaluationContext context = evaluation.getContext();
51	            if (context.getAttributes() != null && context.getAttributes().exists(CONTEXT_TIME_ENTRY)) {
52	                Attributes.Entry contextTimeEntry = context.getAttributes().getValue(CONTEXT_TIME_ENTRY);
53	                if (!contextTimeEntry.isEmpty()) {
54	                    contextTime = contextTimeEntry.asString(0);
55	                }
56	            }
57	            Date actualDate = contextTime == null ? new Date() : dateFormat.parse(contextTime);
58	
59	            String notBefore = policy.getConfig().get("nbf");
60	            if (notBefore != null && !"".equals(notBefore)) {
61	                if (actualDate.before(dateFormat.parse(format(notBefore)))) {
62	                    logger.debugv("Provided date is before the accepted date: (nbf) {0}", notBefore);
63	                    evaluation.deny();
64	                    return;
65	                }
66	            }
67	
68	            String notOnOrAfter = policy.getConfig().get("noa");
69	            if (notOnOrAfter != null && !"".equals(notOnOrAfter)) {
70	                if (actualDate.after(dateFormat.parse(format(notOnOrAfter)))) {
71	                    logger.debugf("Provided date is after the accepted date: (noa) %s", notOnOrAfter);
72	                    evaluation.deny();
73	                    return;
74	                }
75	            }
76	
77	            if (isInvalid(actualDate, Calendar.DAY_OF_MONTH, "dayMonth", policy)
78	                    || isInvalid(actualDate, Calendar.MONTH, "month", policy)
79	                    || isInvalid(actualDate, Calendar.YEAR, "year", policy)
80	                    || isInvalid(actualDate, Calendar.HOUR_OF_DAY, "hour", policy)
81	                    || isInvalid(actualDate, Calendar.MINUTE, "minute", policy)) {
82	                logger.debugf("Invalid date provided to time policy %s", policy.getName());
83	                evaluation.deny();
84	                return;
85	            }
86	
87	            evaluation.grant();
88	        } catch (Exception e) {
89	            throw new RuntimeException("Could not evaluate time-based policy [" + policy.getName() + "].", e);
90	        }
91	    }
92	
93	    private boolean isInvalid(Date actualDate, int timeConstant, String configName, Policy policy) {
94	        Calendar calendar = Calendar.getInstance();
95	
96	        calendar.setTime(actualDate);
97	
98	        int dateField = calendar.get(timeConstant);
99	
100	        if (Calendar.MONTH == timeConstant) {
101	            dateField++;
102	        }
103	
104	        String start = policy.getConfig().get(configName);
105	        if (!isBlank(start)) {
106	            String end = policy.getConfig().get(configName + "End");
107	            if (!isBlank(end)) {
108	                if (dateField < Integer.parseInt(start.trim())  || dateField > Integer.parseInt(end.trim())) {
109	                    return true;
110	                }
111	            } else {
112	                if (dateField != Integer.parseInt(start.trim())) {
113	                    return true;
114	                }
115	            }
116	        }
117	        return false;
118	    }
119	
120	    private static boolean isBlank(String value) {
121	        return value == null || value.trim().isEmpty();
122	    }
123	
124	    static String format(String notBefore) {
125	        String trimmed = notBefore.trim();
126	
127	        if (trimmed.length() == 10) {
128	            notBefore = trimmed + " 00:00:00";
129	        }
130	
131	        return notBefore;
132	    }
133	
134	    @Override
135	    public void close() {
136	
137	    }
138	}
