        Date actualDate = contextTime == null ? new Date() : dateFormat.parse(contextTime);

        String notBefore = policy.getConfig().get("nbf");
        if (notBefore != null && !"".equals(notBefore)) {
            if (actualDate.before(dateFormat.parse(format(notBefore)))) {
